function maxMeetings(starts, ends) {
  const order = starts.map((s, i) => i)
  order.sort((x, y) => ends[x] - ends[y])
  let count = 0
  let lastEnd = -1
  for (const i of order) {
    if (starts[i] > lastEnd) {
      count += 1
      lastEnd = ends[i]
    }
  }
  return count
}

